import pandas as pd


def solve(daily_sales: pd.DataFrame) -> pd.DataFrame:
    df = daily_sales.copy()
    df["units"] = df["units"].fillna(0)

    parts = []
    for product_id, g in df.groupby("product_id"):
        per_day = g.groupby("sale_date")["units"].sum()
        days = pd.date_range(per_day.index.min(), per_day.index.max(), freq="D")
        per_day = per_day.reindex(days, fill_value=0)
        parts.append(
            pd.DataFrame(
                {
                    "product_id": product_id,
                    "sale_date": days,
                    "units": per_day.to_numpy(),
                    "rolling_7d_avg": per_day.rolling(7, min_periods=1).mean().round(2).to_numpy(),
                }
            )
        )
    return pd.concat(parts, ignore_index=True)

