import pandas as pd

def solve(daily_sales):
    df = daily_sales.dropna(subset=["units"])
    parts = []
    for pid, g in df.groupby("product_id"):
        s = g.groupby("sale_date")["units"].sum()
        d = pd.date_range(s.index.min(), s.index.max(), freq="D")
        s = s.reindex(d, fill_value=0)
        parts.append(pd.DataFrame({"product_id": pid, "sale_date": d, "units": s.to_numpy(), "r": s.rolling(7, min_periods=1).mean().round(2).to_numpy()}))
    return pd.concat(parts, ignore_index=True)
